from pathlib import Path
import json,html
OUT=Path(__file__).resolve().parents[1];ROOT=OUT.parents[2];FW=ROOT/'Framework-Edicion-Social';M=json.loads((OUT/'variantes-largas/manifest.json').read_text());P=json.loads((OUT/'plan-mezcla.json').read_text());groups=[]
for id,title,duration in [('largo-53','Retrabajo acelerado',52.93),('largo-159','De atención a ventas',158.798)]:
 variants=[]
 for m in M:
  if m['id']==id:
   variants.append({'id':m['variant'],'title':m['title'],'description':{'A':'Pulso presente, pasos definidos y bajadas por frase.','B':'Más piano y textura acústica, transiciones suaves.','C':'Más anticipaciones, acentos y cambios de carácter.'}[m['variant']],'files':{role:f"variantes-largas/{id}/{m['variant']}/{role}.m4a" for role in ['mezcla','musica','efectos']},'fx_count':len(m['sfx_events']),'music_count':len({q['music'] for q in m['music_clips']})})
 variants.append({'id':'0','title':'Primera prueba','description':'La primera mezcla se conserva para comparar.','files':{role:f'renders/v2/{id}-{role}.m4a' for role in ['mezcla','musica','efectos']}})
 groups.append({'id':id,'title':title,'duration':duration,'chapters':next(p['chapters'] for p in P if p['id']==id),'voice':f'renders/v2/{id}-voz-sola.m4a','variants':variants})
# All credits for actual palette, not only the earlier first trial.
cat=json.loads((FW/'library/music/catalogo-editorial.json').read_text());names=['Neon','Resonance','Sarsaparilla','Backbay Lounge','Clean Soul','Cipher'];credits=[next(t['credit'] for t in cat['tracks'] if t['type']=='bgm' and t['title'].startswith(name)) for name in names]
(OUT/'CREDITOS_VARIANTES.md').write_text('# Créditos de las seis variantes\n\n'+'\n\n'.join(credits)+'\n\nCambios musicales: extractos, remuestreo, ganancia, fades, filtros, control de estéreo, carve dinámico y automatización. No se usa audio extraído de las referencias.\n\nOchoSFX de síntesis original del proyecto, CC0 1.0: library/sfx/candidates/2026-09-30-musicalizacion/manifest.json (ruta desdeFramework-Edicion-Social). Estos candidatos no están aprobados globalmente. Derivados aplican ganancia, paneo leve y protección de cola.\n')
template='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparar musicalización · seis versiones largas</title><style>*{box-sizing:border-box}body{margin:0;background:#eeebe4;color:#26322c;font-family:system-ui,-apple-system,sans-serif}main{max-width:1050px;margin:auto;padding:45px 22px 70px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.15em;font-weight:700;color:#617368}h1{font-size:clamp(32px,5vw,48px);letter-spacing:-.045em;line-height:1.08;margin:12px 0 15px}header p{max-width:670px;line-height:1.6;color:#64756a}.cards{display:grid;gap:24px;margin-top:32px}article{background:#fcfaf6;border:1px solid #d6ddd2;border-radius:20px;padding:28px}h2{font-size:25px;letter-spacing:-.03em;margin:12px 0 20px}.meta{font-size:12px;color:#718278;display:flex;justify-content:space-between}.selectors{display:grid;grid-template-columns:1fr 1fr;gap:16px}.selectors label{display:block;font-size:12px;color:#61746a;margin-bottom:7px}.selectors select{width:100%;font:inherit;font-size:15px;padding:11px 12px;background:#fff;border:1px solid #ced8cf;border-radius:9px;color:#284537}.description{font-size:14px;line-height:1.5;color:#6c7c71;margin:16px 0 18px}.play{border:0;border-radius:10px;font:inherit;background:#244d3e;color:white;padding:12px 23px;cursor:pointer}audio{display:block;width:100%;margin-top:16px;height:45px}.chapters{display:flex;flex-wrap:wrap;gap:8px;margin-top:20px}.chapters button{font-size:12px;padding:8px 10px;border:1px solid #d5dfd4;border-radius:8px;color:#4c6656;background:transparent;cursor:pointer}.download{display:inline-block;font-size:12px;color:#42624c;margin-top:18px}.status{font-size:12px;min-height:17px;color:#78887c;margin-top:12px}.error{color:#a43}details{margin-top:30px;font-size:13px;color:#68766c;line-height:1.6}summary{cursor:pointer}footer{font-size:12px;color:#7f887e;margin-top:30px}a{color:#355e49}button:focus-visible,select:focus-visible{outline:3px solid #a0c6b2;outline-offset:2px}@media(max-width:620px){main{padding:30px 15px 50px}article{padding:20px}.selectors{grid-template-columns:1fr;gap:12px}h2{font-size:23px}}
</style></head><body><main><header><div class="eyebrow">Seis mezclas nuevas · dos mensajes completos</div><h1>Escucha cómo cambia el relato.</h1><p>Tres tratamientos para cada voz. Cambia de versión durante la reproducción para comparar el mismo momento. También puedes escuchar solo la música, los efectos o la voz.</p></header><div class="cards" id="cards"></div><details><summary>Pruebas anteriores, créditos y proceso</summary><p><a href="index.html">Las tres pruebas cortas y las primeras mezclas largas</a></p><div id="credits"></div><p><a href="CREDITOS_VARIANTES.md">Créditos completos</a> · <a href="PROCESO_VARIANTES.md">Proceso y verificaciones</a></p></details><footer>La elección final de carácter y naturalidad necesita tu escucha.</footer></main><script>
const groups=__DATA__;const playing=[];const clock=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');
for(const p of groups){const card=document.createElement('article');card.id='prueba-'+p.id;
card.innerHTML='<div class="meta"><span>VOZ ARTIFICIAL EXISTENTE · TRES TRATAMIENTOS</span><span>'+clock(Math.round(p.duration))+'</span></div><h2>'+p.title+'</h2><div class="selectors"><div><label for="tratamiento-'+p.id+'">Tratamiento de '+p.title+'</label><select id="tratamiento-'+p.id+'">'+p.variants.map(v=>'<option value="'+v.id+'">'+v.title+'</option>').join('')+'</select></div><div><label for="capa-'+p.id+'">Capa de '+p.title+'</label><select id="capa-'+p.id+'"><option value="mezcla">Mezcla completa</option><option value="voz">Voz sola</option><option value="musica">Música aplicada</option><option value="efectos">Efectos aplicados</option></select></div></div><p class="description"></p><button class="play" aria-label="Reproducir '+p.title+'">Escuchar</button><audio controls preload="metadata" aria-label="Audio de '+p.title+'" src="'+p.variants[0].files.mezcla+'"></audio><div class="chapters"></div><div class="status" aria-live="polite"></div><a class="download" download href="'+p.variants[0].files.mezcla+'">Descargar esta mezcla</a>';
document.getElementById('cards').append(card);const audio=card.querySelector('audio');playing.push(audio);const play=card.querySelector('.play');const treatment=card.querySelector('#tratamiento-'+p.id);const layer=card.querySelector('#capa-'+p.id);const description=card.querySelector('.description');const status=card.querySelector('.status');const download=card.querySelector('.download');let change=0;
const chosen=()=>p.variants.find(v=>v.id===treatment.value);const setDescription=()=>{description.textContent=chosen().description;download.href=chosen().files.mezcla};setDescription();const start=()=>audio.play().catch(()=>status.textContent='Pulsa Escuchar para reproducir.');
audio.addEventListener('play',()=>{playing.filter(x=>x!==audio).forEach(x=>x.pause());play.textContent='Pausar';play.setAttribute('aria-label','Pausar '+p.title)});audio.addEventListener('pause',()=>{play.textContent='Escuchar';play.setAttribute('aria-label','Reproducir '+p.title)});audio.addEventListener('error',()=>{status.classList.add('error');status.textContent='No pudo cargarse el audio. Usa Descargar esta mezcla.'});play.addEventListener('click',()=>audio.paused?start():audio.pause());
const swap=()=>{const time=audio.currentTime;const resume=!audio.paused;const generation=++change;audio.pause();setDescription();audio.addEventListener('loadedmetadata',()=>{if(generation!==change)return;audio.currentTime=Math.min(time,audio.duration||p.duration);status.textContent=chosen().title+' · '+layer.selectedOptions[0].textContent+' · '+clock(time);if(resume)start()},{once:true});audio.src=layer.value==='voz'?p.voice:chosen().files[layer.value];audio.load()};treatment.addEventListener('change',swap);layer.addEventListener('change',swap);
for(const [t,label] of p.chapters){const b=document.createElement('button');b.textContent=clock(Math.round(t))+' · '+label;b.addEventListener('click',()=>{audio.currentTime=t;status.textContent=label+' · '+clock(t);start()});card.querySelector('.chapters').append(b)}
}
document.getElementById('credits').innerHTML=__CREDITS__;
</script></body></html>'''
(OUT/'variantes.html').write_text(template.replace('__DATA__',json.dumps(groups,ensure_ascii=False)).replace('__CREDITS__',json.dumps(''.join('<p>'+html.escape(c)+'</p>' for c in credits),ensure_ascii=False)))
index=OUT/'index.html';s=index.read_text();add='<p><a href="variantes.html">Comparar seis versiones nuevas de las piezas largas →</a></p>'
if add not in s:index.write_text(s.replace('</header>',add+'</header>',1))
print('VARIANT BANK READY',OUT/'variantes.html')
